void mainImage( out vec4 fragColor, in vec2 fragCoord )
{
    // Normalized pixel coordinates (from 0 to 1)
    vec2 normalizedCoord = fragCoord/iResolution.xy *2.0 - 1.0;
    vec2 cen = 0.5*iResolution.xy/iResolution.x;
    vec4 m = iMouse / iResolution.x;
    float sinModifier = .25;

    normalizedCoord *= 1.59;

    float val = 0.12;
    val += sin(iTime*(sinModifier+.25))*.095;

    // float iterVal = 16. + abs(sin(iFrame)*16.));

    for (float i = 0.0; i < 38.0; i += 1.0){

    normalizedCoord = abs(normalizedCoord);
    normalizedCoord -= .325 + abs(sin(iTime)*0.25);  // was .5 on first
    normalizedCoord *= 1.1 - abs(sin(iTime)*.05);
    normalizedCoord *= mat2(
        cos(val+m.y*.5), -sin(val+m.x*.5),
        sin(val-m.y*-.5), cos(val)
    );

    };


    // Output to screen
    fragColor = vec4(vec3(length(normalizedCoord)), 1.0);
}
